	}
}

func TestConcurrentOverlappingRegistrationsLeaveSingleRecord(t *testing.T) {
	st := openStore(t)
	ctx := context.Background()

	const goroutines = 32
	var wg sync.WaitGroup
	createdCount := make(chan bool, goroutines)
