	got := []string{envelope.Items[0].ID, envelope.Items[1].ID, envelope.Items[2].ID}
	want := []string{"A", "z", "中"}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("order = %v, want %v", got, want)
